-- Seed: MORA/KHEU prayer times, 2026-10-01 .. 2026-12-31.
-- One row per prayer time; regenerate with `pnpm import:mora --sql`.
on conflict (prayer_date, district, prayer) do update set
  time = excluded.time,
  hijri_date = excluded.hijri_date,
  source_url = excluded.source_url,
  updated_at = now();
